mapper.select:
SELECT 
  FROM public."NET_ブラウザ端末情報"
 WHERE "利用者アカウントID" = #{accountId}
   AND "端末識別子" = #{deviceId}

mapper.update:
UPDATE public."NET_ブラウザ端末情報"
   SET "最終心拍日時" = #{heartbeatAt},
       "更新元コード" = 'BROWSER',
       "バージョン"   = "バージョン" + 1,
       "更新日時"     = CURRENT_TIMESTAMP
 WHERE "利用者アカウントID" = #{accountId}
   AND "端末識別子" = #{deviceId}
   AND "バージョン" = #{version}
